WITH with_gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL 15 MINUTES THEN 1 ELSE 0 END AS new_group_flag FROM device_readings), sessions_device_readings AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, device_code, CASE WHEN new_group_flag >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS new_group_flag_tier, APPROX_PERCENTILE(new_group_flag, ARRAY(0.25, 0.5, 0.75)) AS new_group_flag_quartiles, APPROX_PERCENTILE(pressure, ARRAY(0.25, 0.5, 0.75)) AS pressure_quartiles, BIT_OR(status_bits) AS status_bits_bit_or, COUNT_IF(device_code = 'DV-03') AS dv_03_events, SUM(CASE WHEN device_code = 'DV-02' THEN session_no ELSE 0 END) AS dv_02_session_no, ROUND(AVG(status_bits), 2) AS avg_status_bits FROM sessions_device_readings GROUP BY activity_day, device_code, new_group_flag_tier HAVING avg_status_bits > 0;
